-- European Union deep-dive content: page, stats, file_format cards, scope_transmission
-- cards, steps, penalties_related cards, 2 portals. No lifecycle card (this is a
-- policy-framework overview, not a single national clearance flow) and no penalty rows
-- (ViDA sets the framework; fines remain a national competence).
-- Authored fresh (no legacy static page existed for the EU) from the official EC ViDA
-- page and CEN's EN 16931-1:2026 announcement, both verified via live research.

INSERT OR IGNORE INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-01' FROM countries WHERE name_en = 'European Union';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Phased EU-wide framework — ViDA (2025–2035)', 'This deep-dive page reflects the official European Commission ViDA guidance and CEN''s EN 16931-1:2026 standard as of August 2026, and is provided for general awareness, not legal or tax advice. ViDA sets an EU-wide framework — it does not replace or override any single member state''s own domestic e-invoicing mandate. Check the tracker''s individual country pages for what''s actually mandatory where you invoice today, and confirm current developments directly with the European Commission''s Taxation and Customs Union before making infrastructure decisions.', 'ViDA isn''t a single deadline — it''s three pillars phasing in on three different schedules between 2025 and 2035, layered on top of whatever domestic mandate your own member state already runs.', 'ViDA standardises the data model, not a single national transmission network — EN 16931 defines what a compliant e-invoice must contain, not how every member state must deliver it.', 'This page covers the EU-wide ViDA framework itself, not any single country''s domestic mandate. ViDA is built on three pillars running on different timelines: real-time Digital Reporting Requirements for cross-border B2B trade (from 2030), updated VAT rules for the platform economy (from 2028), and a Single VAT Registration model extending the existing One Stop Shop (phased from 2027). Check the tracker''s individual country pages — Italy, Belgium, Poland, and others — for what''s actually mandatory in the market where you invoice today.', 'What to actually do depends on which pillar affects you, and when — a short-term rental platform preparing for 2028 has a different checklist from a cross-border B2B trader preparing for 2030.', 'ViDA itself doesn''t set a fine schedule — enforcement remains a national competence, so penalties for non-compliance will look like whatever your own member state already applies (or introduces) for its own domestic mandate.' FROM countries WHERE name_en = 'European Union';

